#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    double fa = *(const double *)a;
    double fb = *(const double *)b;
    if (fa < fb) return -1;
    if (fa > fb) return 1;
    return 0;
}

int main() {
    double T;
    int N;

    if (scanf("%lf", &T) != 1) return 0;
    if (scanf("%d", &N) != 1) return 0;

    double *X = (double *)malloc(N * sizeof(double));
    for (int i = 0; i < N; i++) {
        scanf("%lf", &X[i]);
    }

    qsort(X, N, sizeof(double), compare);

    double min_len = (X[0] + X[1]) / 2.0;

    for (int i = 1; i < N - 1; i++) {
        double len = (X[i + 1] - X[i - 1]) / 2.0;
        if (len < min_len) {
            min_len = len;
        }
    }

    double last_len = T - (X[N - 2] + X[N - 1]) / 2.0;
    if (last_len < min_len) {
        min_len = last_len;
    }

    printf("%.2f\n", min_len);

    free(X);
    return 0;
}
